package tt.acid.visuals;
import net.minecraft.client.gui.DrawContext;
import net.minecraft.client.gui.screen.Screen;
import net.minecraft.text.Text;
import org.lwjgl.glfw.GLFW;
public final class AcidVisualsScreen extends Screen {
 private static final int BG=0xF20B0D13,CARD=0xFF171B25,HOVER=0xFF252B39,ACC=0xFFB7A0FF,WHITE=0xFFF5F5FC,MUTED=0xFF9CA3B5;
 private static final String[] TABS={"VISUALS","HUD","PROTECTION"}; private int tab; private float anim; private long last=System.nanoTime();
 public AcidVisualsScreen(){super(Text.literal("AcidVisuals"));} @Override public boolean shouldPause(){return false;}
 @Override public void tick(){long n=System.nanoTime();anim=Math.min(1,anim+Math.min(.05f,(n-last)/1e9f)*5.5f);last=n;}
 @Override public void render(DrawContext c,int mx,int my,float d){float a=1-(float)Math.pow(1-anim,3);c.fill(0,0,width,height,alpha(0xFF05070C,(int)(150*a)));int w=Math.min(690,width-30),h=Math.min(410,height-30);if(w<320||h<250){c.drawCenteredTextWithShadow(textRenderer,Text.literal("Увеличьте размер окна"),width/2,height/2,WHITE);return;}int x=(width-w)/2,y=(height-h)/2+(int)((1-a)*12);round(c,x,y,w,h,20,alpha(BG,(int)(242*a)));round(c,x+18,y+18,4,h-36,2,alpha(ACC,(int)(255*a)));txt(c,"ACID",x+35,y+24,WHITE);txt(c,"VISUALS",x+77,y+24,ACC);small(c,"FABRIC CLIENT  /  MINECRAFT 1.21.4",x+35,y+44,MUTED);small(c,"RIGHT SHIFT · CLOSE",x+w-151,y+28,MUTED);round(c,x+34,y+65,w-68,1,1,0xFF343A49);
 int ny=y+81,tw=125;for(int i=0;i<3;i++){int tx=x+35+i*(tw+8);boolean active=i==tab;round(c,tx,ny,tw,32,10,active?0xFF302A47:inside(mx,my,tx,ny,tw,32)?HOVER:CARD);if(active)round(c,tx+16,ny+27,tw-32,2,1,ACC);c.drawCenteredTextWithShadow(textRenderer,Text.literal(TABS[i]),tx+tw/2,ny+11,active?WHITE:MUTED);}
 txt(c,tab==0?"Visual modules":tab==1?"HUD & overlays":"LAN world protection",x+36,ny+49,WHITE);small(c,tab==2?"Проверки на стороне хоста одиночного мира":"Плавный интерфейс и настраиваемые визуальные функции",x+36,ny+69,MUTED);String[][] rs=rows();int sy=ny+96;for(int i=0;i<rs.length;i++){int ry=sy+i*49;round(c,x+36,ry,w-72,42,11,inside(mx,my,x+36,ry,w-72,42)?HOVER:CARD);txt(c,rs[i][0],x+49,ry+7,WHITE);small(c,rs[i][1],x+49,ry+24,MUTED);boolean on=state(i);int sx=x+w-91;round(c,sx,ry+12,38,18,9,on?0xFF7560E9:0xFF343B4A);round(c,sx+(on?21:3),ry+14,14,14,7,0xFFFFFFFF);}super.render(c,mx,my,d);}
 private String[][] rows(){if(tab==0)return new String[][]{{"Jump Circle","Круговой эффект при прыжке"},{"Player ESP","Подсветка и имена игроков"},{"Entity Hitboxes","Границы сущностей"}};if(tab==1)return new String[][]{{"Target HUD","Информация о цели под прицелом"},{"Smooth UI","Анимации и сглаженные панели"}};return new String[][]{{"LAN AntiCheat","Запрет полёта в выживании"},{"Movement checks","Дополнительные проверки движения"}};}
 private boolean state(int i){if(tab==0)return i==0?AcidVisualsClientSettings.jumpCircleEnabled:i==1?AcidVisualsClientSettings.playerEspEnabled:AcidVisualsClientSettings.entityHitboxesEnabled;if(tab==1)return i==0?AcidVisualsClientSettings.targetHudEnabled:AcidVisualsClientSettings.smoothUiEnabled;return i==0?AcidVisualsClientSettings.antiCheatEnabled:AcidVisualsClientSettings.movementChecksEnabled;}
 private void toggle(int i){if(tab==0){if(i==0)AcidVisualsClientSettings.jumpCircleEnabled=!AcidVisualsClientSettings.jumpCircleEnabled;if(i==1)AcidVisualsClientSettings.playerEspEnabled=!AcidVisualsClientSettings.playerEspEnabled;if(i==2)AcidVisualsClientSettings.entityHitboxesEnabled=!AcidVisualsClientSettings.entityHitboxesEnabled;}else if(tab==1){if(i==0)AcidVisualsClientSettings.targetHudEnabled=!AcidVisualsClientSettings.targetHudEnabled;if(i==1)AcidVisualsClientSettings.smoothUiEnabled=!AcidVisualsClientSettings.smoothUiEnabled;}else if(i==0)AcidVisualsClientSettings.antiCheatEnabled=!AcidVisualsClientSettings.antiCheatEnabled;else AcidVisualsClientSettings.movementChecksEnabled=!AcidVisualsClientSettings.movementChecksEnabled;}
 @Override public boolean mouseClicked(double mx,double my,int b){if(b!=0)return super.mouseClicked(mx,my,b);int w=Math.min(690,width-30),h=Math.min(410,height-30),x=(width-w)/2,y=(height-h)/2,ny=y+81,tw=125;for(int i=0;i<3;i++)if(inside(mx,my,x+35+i*(tw+8),ny,tw,32)){tab=i;return true;}for(int i=0;i<rows().length;i++)if(inside(mx,my,x+36,ny+96+i*49,w-72,42)){toggle(i);return true;}if(!inside(mx,my,x,y,w,h)){if(client!=null)client.setScreen(null);return true;}return true;}
 @Override public boolean keyPressed(int k,int s,int m){if(k==GLFW.GLFW_KEY_ESCAPE||k==GLFW.GLFW_KEY_RIGHT_SHIFT){if(client!=null)client.setScreen(null);return true;}return super.keyPressed(k,s,m);}
 private void txt(DrawContext c,String s,int x,int y,int col){c.drawTextWithShadow(textRenderer,Text.literal(s),x,y,col);}private void small(DrawContext c,String s,int x,int y,int col){c.drawText(textRenderer,Text.literal(s),x,y,col,false);}private static int alpha(int c,int a){return(Math.max(0,Math.min(255,a))<<24)|(c&0xFFFFFF);}
 private static void round(DrawContext c,int x,int y,int w,int h,int r,int col){if(w<=0||h<=0)return;r=Math.max(0,Math.min(r,Math.min(w/2,h/2)));c.fill(x+r,y,x+w-r,y+h,col);c.fill(x,y+r,x+w,y+h-r,col);for(int i=0;i<r;i++){int q=(int)Math.ceil(r-Math.sqrt(Math.max(0,r*r-(r-i-.5)*(r-i-.5))));c.fill(x+q,y+i,x+w-q,y+i+1,col);c.fill(x+q,y+h-i-1,x+w-q,y+h-i,col);}}
 private static boolean inside(double mx,double my,int x,int y,int w,int h){return mx>=x&&mx<=x+w&&my>=y&&my<=y+h;}
}
